import {cities} from './cities.js';
export {cities};
const button=(text,url,outline=false)=>`<a class="button ${outline?'outline':''}" href="${url}">${text}</a>`;
const end=()=>`<section class="final-cta"><span class="eyebrow">YOUR NEXT ARRIVAL</span><h2>Consider it arranged.</h2><p>Choose a vehicle category and service, or tell us the details of a more personal itinerary.</p>${button('Reserve Your Ride','/reserve/')}</section>`;
const questions=items=>`<div class="faq">${items.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div>`;
export function logoHero(){return `<section class="hero logo-hero" aria-label="Martinez Logistics Chauffeur Service"><div class="brand-halo" aria-hidden="true"></div><div class="brand-film" aria-hidden="true"><div class="brand-rule"></div><div class="brand-reveal"><img src="/assets/logo.webp" width="800" height="447" alt="" fetchpriority="high" decoding="async"><span class="brand-sheen"></span></div><span class="brand-signature">PRECISION. PRESENCE. PEACE OF MIND.</span><div class="brand-rule lower"></div></div><div class="entrance"><span class="eyebrow">MARTINEZ LOGISTICS LLC · ATLANTA</span><h1>The Art<br>of <em>Arriving.</em></h1><p>Private chauffeur service.<br>Every detail, considered.</p><div class="actions">${button('Reserve Your Ride','/reserve/')}${button('Enter the Showroom','/fleet/',true)}</div></div><div class="hero-bottom"><span>ATLANTA & THE SURROUNDING CITIES</span><a href="#introduction">DISCOVER MARTINEZ</a></div></section>`}
export function storyPage(){return `<div class="page story-page"><div class="story-opening"><div><span class="eyebrow">OUR STORY / EST. 2016</span><h1>Built on trust.<br><em>Driven by care.</em></h1><p class="editorial-lead">A single box truck. A clear promise.<br>A new expression of professional transportation.</p></div><div class="story-seal"><img src="/assets/logo.webp" width="480" height="268" alt="Martinez Logistics LLC Chauffeur Service" decoding="async"><span>DEPENDABILITY, FROM THE BEGINNING</span></div></div><section class="story-chapter"><span class="chapter-year">2016</span><div><span class="eyebrow">THE FOUNDATION</span><h2>One truck.<br>A reputation earned.</h2><p>Martinez Logistics LLC began in 2016 with a 26-foot box truck and a mission to provide dependable, professional transportation. Pickups and deliveries for businesses built the foundation: arrive when promised, handle every responsibility carefully, and put the customer first.</p><p>Over the years, punctuality, dedication and careful handling became more than operating standards. They became the promise behind the Martinez name.</p></div></section><section class="story-chapter"><span class="chapter-year">2025</span><div><span class="eyebrow">A NEW EXPRESSION</span><h2>The same discipline.<br>A more personal journey.</h2><p>In 2025, Martinez Logistics expanded into luxury black car and limousine transportation. The operational discipline developed in logistics became the foundation for a chauffeur service serving corporate clients, special events, airport transfers and high-profile travel.</p><p>Professional chauffeurs, meticulously maintained vehicles and a commitment to safety, discretion and on-time performance guide this new chapter. The purpose remains familiar: take responsibility for the journey, so the customer can focus on what comes next.</p></div></section><section class="story-values"><span class="eyebrow">THE PROMISE TODAY</span><h2>Care you can feel.<br>Standards you can trust.</h2><div class="editorial-columns"><article><span class="number">01</span><h3>Professional, from pickup.</h3><p>Trained chauffeurs bring attention to punctuality, privacy and safe travel. From an executive appointment to a family airport departure, the details of your journey receive personal consideration.</p></article><article><span class="number">02</span><h3>Connected to your plans.</h3><p>Flight monitoring, real-time updates and coordinated meet-and-greet arrangements help bring the handoffs together. Share flight information and pickup requirements when arranging your transfer.</p></article><article><span class="number">03</span><h3>Comfort along the way.</h3><p>Clean, maintained vehicles and climate-controlled comfort create space to settle in. Confirm Wi-Fi, charging, seating and luggage requirements for your selected vehicle when booking.</p></article></div></section><section class="story-closing"><span class="eyebrow">FROM CURBSIDE TO TAKEOFF</span><h2>Your journey.<br>Our responsibility.</h2><p>From a single truck to a luxury chauffeur service, Martinez Logistics continues to build on the same foundations: reliability, professional care and a customer-first approach.</p>${button('Explore Our Services','/services/',true)}</section></div>${end()}`}
const serviceDetails={
 'airport-transfers':{eyebrow:'FLIGHT MONITORING / ARRIVAL COORDINATION',title:'The flight is yours.<br>The drive is ours.',paragraphs:['An airport transfer is more than the distance between a terminal and an address. It starts with the flight details, the size of your party and the luggage coming with you. Martinez Logistics brings flight monitoring, luggage assistance and coordinated pickup arrangements to ATL arrivals and departures.','For arrivals, provide the airline, flight number and destination, then confirm the meeting instructions with the company. For departures, include the exact pickup address and flight time so the collection can be planned around check-in and the day’s journey. Meet-and-greet requirements should be arranged in advance.'],features:[['On arrival','Share the actual arriving flight, even when the reservation is being made by a host. Keep your contact number available for pickup updates, and confirm the meeting location before leaving the terminal.'],['Before departure','Use the airline’s recommended arrival window when discussing your pickup. Include any intermediate stop, gate access and the number of bags so the vehicle and timing fit the whole journey.'],['For your party','Choose Sedan, SUV or Sprinter by the needs of the complete group. Confirm seating, luggage capacity, child-seat requests and accessibility requirements before reserving.']],prepare:['Airline and flight number','Domestic or international arrival details','Pickup and destination addresses','Passengers, bags and special requirements'],faqs:[['Where will I meet my chauffeur at ATL?','Confirm your meeting instructions directly with the company for your terminal and selected service. Follow the agreed pickup plan and the airport’s current vehicle access rules; meet-and-greet requests should be arranged in advance.'],['Is an arrival booking different from a departure?','Yes. The live booking menu has separate ATL arrival and departure listings for each vehicle category. Choose the correct direction before selecting an appointment.'],['Can my transfer include another stop?','Tell the company about every stop before booking. The route, extra time and any additional charges need to be agreed rather than assumed to be included in a transfer listing.']]},
 'hourly-chauffeur':{eyebrow:'YOUR ITINERARY / YOUR PACE',title:'A little more room<br>in your day.',paragraphs:['An hourly chauffeur booking gives a planned itinerary one consistent thread. A hotel departure, a sequence of meetings, a lunch reservation or an evening with several destinations can be discussed as a connected journey. It is a useful choice when the day involves more than a single transfer.','The supplied listings show one-hour appointments for Luxury Sedan, Luxury SUV and Luxury Sprinter. Share the full start and finish, the order of stops and the time you need at each destination. Additional hours, waiting, route changes and service arrangements require confirmation with the company.'],features:[['Plan the sequence','Write down the actual order of addresses, with appointment or reservation times. A clear sequence helps establish the time the vehicle will be required.'],['Keep the occasion in view','A business itinerary and an evening out have different pacing. Tell us which arrival times are fixed and which parts of the day can remain flexible.'],['Confirm the full booking','Discuss the total duration and expected finish before booking. A one-hour listing should not be treated as an unlimited period of vehicle availability.']],prepare:['Start address and start time','Every planned destination, in order','Time expected at each stop','Estimated finish and return destination'],faqs:[['Can I reserve more than one hour?','Contact the company with the duration you need. Additional availability, the appropriate booking and the final price should be confirmed before you reserve.'],['Will the chauffeur wait between stops?','Discuss waiting requirements as part of the itinerary, including how long each appointment may take. Waiting and additional time are subject to the arrangements confirmed by the company.'],['Can an hourly journey finish at ATL?','Include the airport as the final destination, with your flight details and any luggage collection stop. The company can confirm the appropriate service and timing for the complete journey.']]},
 'corporate-travel':{eyebrow:'MEETINGS / CONFERENCES / CLIENT VISITS',title:'Business travel,<br>with breathing room.',paragraphs:['Corporate transportation should support the schedule, not become another task inside it. Martinez Logistics provides discreet travel for meetings, conferences and client visits, with professional chauffeurs and transportation plans tailored to the business need.','Arrange an individual executive transfer, discuss a shared guest itinerary, or coordinate transport for colleagues traveling together. For recurring travel, ask about tailored billing and account management. Team movements and shuttle-style arrangements need an agreed vehicle, passenger count, route and operating schedule.'],features:[['A considered welcome','If you are booking for a client, provide the traveler’s name, flight or hotel details, meeting location and an appropriate contact. Clear instructions help make the guest’s arrival straightforward.'],['A coordinated team','For several passengers, share who is traveling together, whether pickup addresses differ and how much luggage or equipment is coming. Confirm capacity rather than assuming every group will fit one vehicle.'],['A repeatable arrangement','For ongoing business travel, discuss the usual routes, booking contacts, billing requirements and any account preferences with the company.']],prepare:['Traveler or group contact details','Office, hotel and venue entrances','Meeting start and finish windows','Billing or account requirements'],faqs:[['Can an assistant book for a visiting client?','Share both the booking contact and the traveler’s reachable contact, together with the full itinerary. Confirm who should receive journey updates and the final booking confirmation.'],['Do you offer business account arrangements?','The company’s original service information includes tailored billing and account management. Contact Martinez Logistics to discuss your requirements and confirm the arrangement.'],['How should we arrange conference transportation?','Send the venue, dates, hotel addresses, group sizes and required arrival windows. Any repeated shuttle movements or additional vehicles should be confirmed as part of a specific plan.']]},
 'executive-transportation':{eyebrow:'PROFESSIONAL CARE / PRIVATE TRAVEL',title:'Arrive ready<br>for what matters.',paragraphs:['Executive transportation brings the company’s emphasis on punctuality, safety and privacy to a more personal itinerary. A professional chauffeur, a maintained vehicle and a clearly arranged journey create space between your appointments.','Use the service for an important meeting, a visiting executive, an airport connection or private travel across Atlanta. Give the company your timing, vehicle preferences and any particular requirements. The category can be selected online; a specific make, model, amenity or special arrangement should be confirmed directly.'],features:[['Discretion throughout','Share only the journey details the company needs, and discuss any sensitive arrival instructions privately. A host or assistant can help coordinate the handoff without leaving the traveler to resolve it.'],['A vehicle that fits','Choose a category with the passenger and luggage requirements in mind. Confirm amenities such as Wi-Fi and charging if they are important to the workday.'],['Time to arrive composed','Include building access, a preferred entrance and the time the traveler must be inside. The useful target is the appointment itself, not simply the street address.']],prepare:['Required arrival time','Preferred building or hotel entrance','Passenger and luggage requirements','Host or assistant contact, if applicable'],faqs:[['Can I request a particular vehicle?','Discuss the requested make, model and amenities with the company before booking. The online menu reserves a category; the representative showroom models are not an availability guarantee.'],['Can my assistant coordinate the journey?','Yes. Provide the assistant’s contact and clarify who should receive updates. Make sure the traveler has the agreed pickup instructions as well.'],['Can the service cover several executive appointments?','Send the full schedule and discuss an hourly arrangement or separate transfers. The company can confirm the service that fits the expected duration and stops.']]},
 'special-events':{eyebrow:'PRIVATE OCCASIONS / GUEST ARRIVALS',title:'The occasion begins<br>before you arrive.',paragraphs:['A memorable evening deserves a journey planned with the same care as the event. Martinez Logistics offers transportation for special occasions, with the timing, party size and return arrangements considered before the day arrives.','Whether you are coordinating guests, attending a performance or planning a private celebration, share the actual venue and the complete sequence of stops. An event charter is arranged around those details. Confirm vehicle capacity, duration, waiting and the final quote directly; an hourly listing does not automatically define every event arrangement.'],features:[['Before the occasion','Give the venue address, the time guests should arrive and any venue instructions for vehicles. If guests are staying at several hotels, identify each pickup clearly.'],['Together, where appropriate','A shared journey can simplify guest coordination. Discuss the Sprinter category for groups, with seating, luggage and accessibility needs checked before confirming a vehicle.'],['The return, considered','Agree on the end-of-event meeting point and expected pickup time. If the finish may move, discuss how updates, waiting and any additional time will be handled.']],prepare:['Venue and event date','Required arrival and return times','Guest count and pickup addresses','Waiting, luggage and access requirements'],faqs:[['How early should I arrange event transport?','Contact the company as soon as the venue and date are known. Vehicle availability and the event plan must be confirmed; browsing a category does not hold a vehicle.'],['Can guests be collected from different hotels?','Provide each hotel address, the guest count at each stop and the time everyone must arrive. Additional stops and vehicles should be included in the confirmed itinerary.'],['What happens if the event finishes later?','Discuss that possibility before the event. Waiting, schedule changes and additional time depend on availability and the terms confirmed by the company.']]}
};
export function servicesIntro(services){return `<div class="page"><div class="editorial-heading"><span class="eyebrow">SIGNATURE SERVICES</span><h1>Your plans.<br><em>Our attention.</em></h1><p class="editorial-lead">From a flight connection to a full business day, choose a service shaped around the way you need to travel.</p></div><div class="service-directory">${services.map((s,i)=>`<article><span class="eyebrow">0${i+1} / MARTINEZ</span><h2>${s.name}</h2><p>${s.intro}</p><p>${serviceDetails[s.slug].paragraphs[0]}</p><a class="text-link" href="/services/${s.slug}/">Discover the details</a></article>`).join('')}</div></div>${end()}`}
export function detailedServicePage(service,rateTable){const d=serviceDetails[service.slug],priced=['airport-transfers','hourly-chauffeur'].includes(service.slug);return `<div class="page service-editorial"><a class="breadcrumb" href="/services/">All services</a><div class="editorial-heading"><span class="eyebrow">${service.name}</span><h1>${d.title}</h1><p class="editorial-lead">${service.intro}</p></div><section class="service-narrative"><span class="eyebrow">${d.eyebrow}</span>${d.paragraphs.map(p=>`<p>${p}</p>`).join('')}</section><section class="service-detail-grid">${d.features.map(([h,p],i)=>`<article><span class="number">0${i+1}</span><h2>${h}</h2><p>${p}</p></article>`).join('')}</section><section class="journey-preparation"><div><span class="eyebrow">A SEAMLESS START</span><h2>A few details.<br>A better journey.</h2><p>Bring these details to your reservation or inquiry so the service can be arranged around your plans.</p></div><ol>${d.prepare.map(p=>`<li>${p}</li>`).join('')}</ol></section>${priced?`<section class="service-rates"><span class="eyebrow">THE PUBLISHED LISTINGS</span><h2>Choose your service.</h2>${rateTable(o=>service.slug==='airport-transfers'?o.type!=='Hourly':o.type==='Hourly')}</section>`:`<section class="service-rates"><span class="eyebrow">YOUR VEHICLE / YOUR ITINERARY</span><h2>Begin with the right category.</h2><p>Explore Sedan, SUV and Sprinter options, then discuss the complete itinerary. Vehicle capacity, amenities and the final arrangements are confirmed for your journey.</p><div class="actions">${button('Explore the Showroom','/fleet/')}${button('Discuss Your Journey','/contact/',true)}</div></section>`}<section class="service-questions"><span class="eyebrow">BEFORE YOU TRAVEL</span><h2>Useful details.</h2>${questions(d.faqs)}</section><section class="service-area-link"><span class="eyebrow">ATLANTA & BEYOND</span><h2>Where are you headed?</h2><p>Explore our Atlanta-area destinations for local pickup guidance, airport connections and ideas for your itinerary.</p>${button('Explore Service Areas','/service-areas/',true)}</section></div>${end()}`}
export function areasDirectory(){return `<div class="page area-directory"><div class="editorial-heading"><span class="eyebrow">OUR SERVICE AREAS / GREATER ATLANTA</span><h1>Atlanta is home.<br><em>The journey is yours.</em></h1><p class="editorial-lead">Chauffeur service across Atlanta, north Fulton, Cobb and Gwinnett. Find your city for airport transfers, business travel and evenings thoughtfully arranged.</p></div><div class="area-intro-strip"><span>ATL</span><p>Hartsfield-Jackson connections.<br>Neighborhood arrivals.<br>One considered experience.</p><a href="/services/airport-transfers/" class="text-link">Explore airport transfers</a></div><div class="city-grid">${cities.map((c,i)=>`<a href="/service-areas/${c.slug}/" class="city-card"><span class="eyebrow">${String(i+1).padStart(2,'0')} / ${c.region}</span><h2>${c.name}</h2><p>${c.intro}</p><span class="city-card-link">Explore ${c.name}</span></a>`).join('')}</div><section class="area-planning"><span class="eyebrow">FROM YOUR ADDRESS TO YOUR ARRIVAL</span><h2>A local plan.<br>A personal journey.</h2><p>Send the exact pickup and destination, your preferred time, and the needs of your party. For multiple stops, group travel or a destination beyond these cities, contact us to arrange the complete itinerary.</p><p>Live availability and final service pricing are confirmed through the booking provider or directly with the company. City pages do not establish a fixed travel time or a separate city fare.</p>${button('Plan Your Journey','/contact/',true)}</section></div>${end()}`}
export function areaPage(slug){const c=cities.find(c=>c.slug===slug);if(!c)return null;return `<div class="page city-page"><a class="breadcrumb" href="/service-areas/">Greater Atlanta service areas</a><div class="city-heading"><span class="eyebrow">${c.region} / CHAUFFEUR SERVICE</span><p class="city-name">${c.name}</p><h1>${c.headline}</h1><p class="editorial-lead">${c.intro}</p><div class="actions">${button('Reserve Your Ride','/reserve/')}${button('Discuss This Journey','/contact/',true)}</div></div><section class="city-context"><div><span class="eyebrow">A SENSE OF PLACE</span><h2>The ${c.name}<br>connection.</h2></div><div><p>${c.story}</p><div class="city-destinations">${c.places.map(p=>`<span>${p}</span>`).join('')}</div><a class="local-reference" href="${c.source}" target="_blank" rel="noopener noreferrer">Explore local destinations with the official city guide</a></div></section><section class="city-airport"><span class="airport-code">ATL</span><div><span class="eyebrow">AIRPORT ARRIVALS & DEPARTURES</span><h2>${c.name},<br>connected to your flight.</h2><p>${c.airport}</p><a class="text-link" href="/services/airport-transfers/">View ATL transfer services and listings</a></div></section><section class="city-journeys"><span class="eyebrow">TRAVEL WITH A PURPOSE</span><h2>A journey for your plans.</h2><div class="city-journey-grid">${c.journeys.map(([h,p],i)=>`<article><span class="number">0${i+1}</span><h3>${h}</h3><p>${p}</p></article>`).join('')}</div></section><section class="city-practical"><span class="eyebrow">A LOCAL DETAIL</span>${questions([[c.question,c.answer]])}<p class="caption">Share your exact addresses, time, passengers and luggage when booking. Final availability, vehicle suitability and pricing are confirmed for the journey.</p></section><section class="nearby-cities"><span class="eyebrow">CONTINUE YOUR JOURNEY</span><h2>Nearby connections.</h2><div>${c.near.map(slug=>cities.find(x=>x.slug===slug)).map(n=>`<a href="/service-areas/${n.slug}/">${n.name}</a>`).join('')}</div></section></div>${end()}`}
